# Helper functions for safe environment parsing
def _parse_env_str(name: str) -> Optional[str]:
    raw = os.environ.get(name)
    if raw is None:
        return None
    value = raw.strip()
    return value if value else None


def _parse_env_int(name: str) -> Optional[int]:
    raw = os.environ.get(name)
    if raw is None or raw.strip() == "":
        return None
    try:
        return int(raw.strip())
    except ValueError:
        return None


def _parse_env_bool(name: str, default: bool = False) -> bool:
    raw = os.environ.get(name)
    if raw is None:
        return bool(default)
    value = raw.strip().lower()
    if value in {"1", "true", "yes", "on"}:
        return True
    if value in {"0", "false", "no", "off"}:
        return False
    return bool(default)


def _parse_env_float(name: str) -> Optional[float]:
    raw = os.environ.get(name)
    if raw is None or raw.strip() == "":
        return None
    try:
        return float(raw.strip())
    except ValueError:
        return None


def _parse_env_int_tuple(
    name: str, default: Tuple[int, ...]
) -> Tuple[int, ...]:
    raw = os.environ.get(name)
    if raw is None or raw.strip() == "":
        return tuple(default)
    try:
        values = tuple(int(item.strip()) for item in raw.split(","))
    except ValueError:
        return tuple(default)
    if not values or any(value <= 0 for value in values):
        return tuple(default)
    return values


