_observation_history_key_count = 0
_observation_reconcile_index: Optional[Dict[str, Any]] = None
_OBSERVATION_RECONCILE_INDEX_SCHEMA_VERSION = 2
_OBSERVATION_RECONCILE_REBUILD_RETRY_SECONDS = 300.0


